import { OrderStatus } from "@prisma/client";
import { getCurrentUser } from "@/lib/auth";
import { z } from "zod";
import { prisma } from "@/lib/prisma";

async function ensureAdmin() {
  const user = await getCurrentUser();
  if (!user || user.role !== "ADMIN") {
    throw new Error("Accès refusé. Privilèges administrateur requis.");
  }
  return user;
}

// 1. Product & Category Administration
export const AdminProductSchema = z.object({
  titleFr: z.string().min(2),
  titleAr: z.string().min(2),
  descriptionFr: z.string().min(5),
  descriptionAr: z.string().min(5),
  price: z.coerce.number().min(0.01),
  oldPrice: z.coerce.number().min(0).optional(),
  categoryId: z.string().uuid(),
  isActive: z.boolean().default(true),
  isFeatured: z.boolean().default(false),
  stock: z.coerce.number().int().min(0),
});

export async function adminCreateProduct(rawInput: unknown) {
  await ensureAdmin();
  const parsed = AdminProductSchema.parse(rawInput);

  const slug = parsed.titleFr
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");

  return await prisma.$transaction(async (tx) => {
    const product = await tx.product.create({
      data: {
        slug: `${slug}-${Date.now().toString().slice(-4)}`,
        titleFr: parsed.titleFr,
        titleAr: parsed.titleAr,
        descriptionFr: parsed.descriptionFr,
        descriptionAr: parsed.descriptionAr,
        price: parsed.price,
        oldPrice: parsed.oldPrice || null,
        categoryId: parsed.categoryId,
        isActive: parsed.isActive,
        isFeatured: parsed.isFeatured,
        inventory: {
          create: { stock: parsed.stock },
        },
        variants: {
          create: [
            {
              nameFr: "Standard",
              nameAr: "قياسي",
              sku: `SKU-${Date.now()}`,
              price: parsed.price,
              stock: parsed.stock,
            },
          ],
        },
      },
      include: { inventory: true, variants: true, category: true },
    });

    return product;
  });
}

export async function adminUpdateInventory(productId: string, newStock: number) {
  await ensureAdmin();

  return await prisma.$transaction(async (tx) => {
    await tx.inventory.update({
      where: { productId },
      data: { stock: newStock },
    });

    // Update primary variant stock as well
    await tx.productVariant.updateMany({
      where: { productId },
      data: { stock: newStock },
    });

    return { success: true, newStock };
  });
}

// 2. Order Management & Audit-safe Operations
export async function adminGetOrders() {
  await ensureAdmin();

  return await prisma.order.findMany({
    include: {
      items: {
        include: { product: true, variant: true },
      },
      user: true,
    },
    orderBy: { createdAt: "desc" },
  });
}

export async function adminUpdateOrderStatus(orderId: string, newStatus: OrderStatus) {
  const admin = await ensureAdmin();

  const order = await prisma.order.findUnique({ where: { id: orderId } });
  if (!order) {
    throw new Error("Commande introuvable");
  }

  // Audit log notation in notes
  const auditNote = `[Audit] Statut changé de ${order.status} à ${newStatus} par Admin (${admin.email}) le ${new Date().toISOString()}`;
  const existingNotes = order.notes ? `${order.notes}\n${auditNote}` : auditNote;

  return await prisma.order.update({
    where: { id: orderId },
    data: {
      status: newStatus,
      notes: existingNotes,
    },
  });
}

export const dynamic = "force-dynamic";

import { getCurrentUser } from "@/lib/auth";
import { redirect } from "next/navigation";
import { prisma } from "@/lib/prisma";
import { Plus, Package, CheckCircle2, XCircle } from "lucide-react";
import Link from "next/link";

export default async function AdminProductsPage() {
  const user = await getCurrentUser();
  if (!user || user.role !== "ADMIN") {
    redirect("/admin/login");
  }

  const products = await prisma.product.findMany({
    include: { category: true, inventory: true, variants: true },
    orderBy: { createdAt: "desc" },
  });

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-black text-white">Catalogue & Produits</h1>
          <p className="text-slate-400 text-sm mt-1">Gérez les produits, stocks et prix de la boutique.</p>
        </div>
        <Link
          href="/admin/products/new"
          className="bg-orange-600 hover:bg-orange-700 text-white font-bold px-5 py-2.5 rounded-xl transition-colors shadow-md flex items-center gap-2 text-sm"
        >
          <Plus className="w-4 h-4" /> Ajouter un produit
        </Link>
      </div>

      <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-lg overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="border-b border-slate-700 text-slate-400 text-xs uppercase tracking-wider">
              <th className="pb-3 font-semibold">Produit</th>
              <th className="pb-3 font-semibold">Catégorie</th>
              <th className="pb-3 font-semibold">Prix</th>
              <th className="pb-3 font-semibold">Stock</th>
              <th className="pb-3 font-semibold">Statut</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-700/60">
            {products.map((product) => (
              <tr key={product.id} className="hover:bg-slate-700/30 transition-colors">
                <td className="py-4 font-bold text-white flex items-center gap-3">
                  <div className="w-10 h-10 bg-slate-700 rounded-xl flex items-center justify-center shrink-0 border border-slate-600">
                    <Package className="w-5 h-5 text-orange-400" />
                  </div>
                  <div>
                    <div>{product.titleFr}</div>
                    <div className="text-xs text-slate-400 font-normal">{product.slug}</div>
                  </div>
                </td>
                <td className="py-4 text-slate-300">{product.category.nameFr}</td>
                <td className="py-4 font-semibold text-orange-400">{Number(product.price).toLocaleString()} MAD</td>
                <td className="py-4 text-slate-300 font-semibold">{product.inventory?.stock ?? 0} unit(s)</td>
                <td className="py-4">
                  {product.isActive ? (
                    <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                      <CheckCircle2 className="w-3.5 h-3.5" /> Actif
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold bg-red-500/20 text-red-300 border border-red-500/30">
                      <XCircle className="w-3.5 h-3.5" /> Inactif
                    </span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

