// Add to the top
import { z } from 'zod';

// Extend existing schema for update
export const AdminProductUpdateSchema = AdminProductSchema.extend({
  id: z.string(),
  descriptionFr: z.string().min(5),
  descriptionAr: z.string().min(5),
  price: z.coerce.number().min(0.01),
  oldPrice: z.coerce.number().min(0).optional(),
  categoryId: z.string().uuid(),
  isActive: z.boolean().default(true),
  isFeatured: z.boolean().default(false),
  stock: z.coerce.number().int().min(0),
  isDraft: z.boolean().default(false),
});

// Update function
export async function adminUpdateProduct(productId: string, data: z.infer<typeof AdminProductUpdateSchema>) {
  await ensureAdmin();
  const parsed = AdminProductUpdateSchema.safeParse(data);
  if (!parsed.success) {
    throw new Error('Données de produit invalides');
  }

  return await prisma.$transaction(async (tx) => {
    const product = await tx.product.findUnique({ where: { id: productId } });
    if (!product) {
      throw new Error('Produit introuvable');
    }

    await tx.product.update({
      where: { id: productId },
      data: {
        titleFr: parsed.titleFr,
        titleAr: parsed.titleAr,
        descriptionFr: parsed.descriptionFr,
        descriptionAr: parsed.descriptionAr,
        price: parsed.price,
        oldPrice: parsed.oldPrice,
        isActive: parsed.isActive,
        isFeatured: parsed.isFeatured,
        categoryId: parsed.categoryId,
        isDraft: parsed.isDraft,
        stock: parsed.stock,
      },
    });

    return product;
  });
}

// Delete (archive) function
export async function adminDeleteProduct(productId: string) {
  await ensureAdmin();
  // Soft delete: set isActive false and isDraft true
  await prisma.product.update({
    where: { id: productId },
    data: {
      isActive: false,
      isDraft: true,
    },
  });
}
```

