import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { z } from "zod";

export default async function ProductEditPage({ params }: { params: { id: string } }) {
  const router = useRouter();
  const { id } = params;
  const product = await getProductBySlug(id);
  const { data, errors, handleSubmit, reset } = useForm<z.infer<typeof AdminProductUpdateSchema>>({
    defaultValues: {
      id: id,
      titleFr: product.titleFr,
      titleAr: product.titleAr,
      descriptionFr: product.descriptionFr,
      descriptionAr: product.descriptionAr,
      price: product.price,
      oldPrice: product.oldPrice,
      categoryId: product.categoryId,
      isActive: product.isActive,
      isFeatured: product.isFeatured,
      stock: product.inventory?.[0]?.stock ?? 0,
      isDraft: product.isDraft,
    },
  });

  const router = useRouter();

  const handleSubmit = async (data: z.infer<typeof AdminProductUpdateSchema>) => {
    try {
      await adminUpdateProduct(id, data);
      router.push("/admin/products");
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    // Ensure product data is loaded
    // Already fetched via getProductBySlug
  }, [id]);

  if (!product) {
    return <p>Produit non trouvé</p>;
  }

  return (
    <div className="max-w-3xl mx-auto p-6">
