          {errors.titleFr && <p className="text-red-500">{errors.titleFr.message}</p>}
        </div>

        <div className="space-y-4">
          <label className="block text-xs font-bold text-slate-300">Titre (Arabe)</label>
          <input
            type="text"
            name="titleAr"
